// The `tick` hook point (once per tick, in every Game (check game.native_window())).
// Generated by horizon-port from Sound Physics Remastered 1.5.2+26.3. It stands in for:
//   Mixin @Inject on ClientPacketListener.handleLogin in ClientPacketListenerMixin.handleLogin: joining a world, seen by the tick hook
//
// Game calls the Java code makes here, and what they are in Horizon:
//   ClientPacketListener.handleLogin -> (not mapped yet)
fn sound_physics_remastered_tick(game: &mut crate::game::Game<'_>) {
    use crate::game::port_sound_physics_remastered as m;
    // Turned off in Options > Mods: nothing until the next build leaves it out.
    if !game.native_on(m::ID) {
        return;
    }
    // The mod's data folder and its initializer, the first time.
    crate::game::port_sound_physics_remastered_game::ensure_init(game);
    // TODO: port the tick handler. game.native_window() is false in the server's Game.
    let _ = (game, &m::ID);
}
